//! Run i/syntax through ordinary i calls and the opaque-reference ABI.
use ilang_syntax::lisp::{
    parse,
    syntax::{Scope, Syntax},
};
use std::collections::BTreeSet;

/// Build test modules as compiler-generated modules, so internal syntax
/// operations are accessible only to the code generated by the compiler.
fn build_generated_tests(project: &std::path::Path, opt: ilang_cli::Level) -> ilang_cli::Built {
    use ilang_package::lock::{FileKind, PackageFile, hash};
    let (graph, diagnostics) = ilang_cli::load(project, true, true);
    assert!(
        !diagnostics.iter().any(ilang_package::Diagnostic::is_error),
        "{:?}",
        graph.sources.render_all(&diagnostics)
    );
    let root = graph.root.unwrap();
    let (mut parsed, diagnostics) = ilang_check::parse(&graph);
    assert!(
        diagnostics.is_empty(),
        "{:?}",
        graph.sources.render_all(&diagnostics)
    );
    for module in &mut parsed {
        if module.package == root && module.kind == ilang_package::ModuleKind::Test {
            module.compiler_generated = true;
        }
    }
    let checked = ilang_check::check_parsed(&graph, &parsed);
    assert!(
        !checked
            .diags
            .iter()
            .any(ilang_package::Diagnostic::is_error),
        "{:?}",
        graph.sources.render_all(&checked.diags)
    );
    let (wasm, declarations) = ilang_wasm::compile_with_bindings(
        &graph,
        checked.program.as_ref().unwrap(),
        checked.types.as_ref().unwrap(),
        ilang_wasm::Options {
            tests: true,
            target: ilang_wasm::Target::Ilang,
        },
    )
    .unwrap();
    let wasm = ilang_cli::optimize(&wasm, opt).unwrap();
    let declarations = declarations
        .into_iter()
        .map(|d| ilang_host::bindings::BindingDeclaration::from_json(&d.to_string()).unwrap())
        .collect();
    let binding_plan = ilang_host::bindings::BindingPlan::new(&wasm, declarations);
    let files = graph.packages[graph.library]
        .modules
        .iter()
        .map(|m| PackageFile {
            path: m.path.clone(),
            kind: FileKind::Regular,
            bytes: graph.sources.get(m.source).text.as_bytes().to_vec(),
        })
        .collect::<Vec<_>>();
    ilang_cli::Built {
        name: graph.packages[root].name.clone(),
        wasm,
        binding_plan,
        trusted_package: hash(&files),
        warnings: vec![],
        tests: true,
        templates: vec![],
    }
}

#[test]
fn syntax_library_round_trips_through_the_host() {
    let dir = tempfile::tempdir().unwrap();
    std::fs::write(dir.path().join("i.toml"), "name = \"app\"\n").unwrap();
    std::fs::create_dir(dir.path().join("test")).unwrap();
    std::fs::write(
        dir.path().join("test/main.i"),
        r#"
(i/fail, syntax = i/syntax)
@external("test:syntax", "source")
source: () -> syntax.Syntax
@test
exercise = () -> Nil ? syntax.SyntaxError ! Assert {
  value = source()
  assert(source() == value)
  ! syntax.Definitions = syntax.Definitions((of) { of })
  assert(syntax.definition(value) == value)
  assert(syntax.show(value) == "(f x)")
  syntax.node(value) |> {
    syntax.Round([first, second]) -> {
      syntax.node(value) |> {
        syntax.Round([again, _]) -> assert(first == again)
        _ -> panic("unexpected syntax node")
      }
      assert(syntax.show(first) == "f")
      assert(syntax.show(second) == "x")
    }
    _ -> panic("unexpected syntax node")
  }
  made = syntax.make(syntax.Name("made"), value)
  assert(syntax.show(made) == "made")
  assert(syntax.same_code(made, made))
  assert(syntax.show_as(made, syntax.Expression) == "made")
  pair = syntax.make(syntax.Round([made, value]), value)
  assert(syntax.show(pair) == "(made (f x))")
  fail.catch(() { syntax.make(syntax.Name("Bad Name"), value) }) |> {
    Error(syntax.SyntaxError(message, at)) -> {
      assert(message != "")
      assert(syntax.same_code(at, value))
    }
    Ok(_) -> panic("invalid syntax atom was accepted")
  }
  comma = syntax.make(syntax.Symbol(","), value)
  bad = syntax.make(syntax.Round([comma]), value)
  fail.catch(() { syntax.show_as(bad, syntax.Expression) }) |> {
    Error(syntax.SyntaxError(message, at)) -> {
      assert(message != "")
      assert(syntax.same_code(at, bad))
    }
    Ok(_) -> panic("invalid expression was accepted")
  }
  Nil
}
"#,
    )
    .unwrap();
    let source = Syntax::from_datum(
        &parse("(f x)").unwrap()[0],
        &Scope {
            module: 3,
            marks: BTreeSet::new(),
        },
    );
    for opt in [ilang_cli::Level::O0, ilang_cli::Level::O2] {
        let built = ilang_cli::build(
            dir.path(),
            ilang_cli::BuildOptions {
                tests: true,
                opt,
                offline: true,
                target: ilang_cli::Target::Ilang,
            },
        )
        .unwrap();
        let mut options = built.host_options();
        let source = source.clone();
        options
            .imports
            .external("test:syntax", "source", move |_| {
                Ok(ilang_host::syntax::encode(source.clone()))
            })
            .unwrap();
        let program = built.host_program().unwrap();
        let result = program.run_test_with("app/main.exercise", options);
        assert!(
            matches!(result, ilang_host::TestResult::Passed),
            "{result:?}"
        );
    }
}

#[test]
fn compiler_operations_are_limited_to_compiler_instances() {
    let dir = tempfile::tempdir().unwrap();
    std::fs::write(dir.path().join("i.toml"), "name = \"app\"\n").unwrap();
    std::fs::create_dir(dir.path().join("src")).unwrap();
    std::fs::write(
        dir.path().join("src/helper.i"),
        r#"
(syntax = i/syntax)
(show)
@external("test:syntax", "source")
source: () -> syntax.Syntax
show = () { syntax.show(source()) }
"#,
    )
    .unwrap();
    let main = dir.path().join("src/main.i");
    let options = ilang_cli::BuildOptions {
        tests: false,
        opt: ilang_cli::Level::O0,
        offline: true,
        target: ilang_cli::Target::Ilang,
    };
    std::fs::write(
        &main,
        "(helper = app/helper)\nmain = () { helper.show()  Nil }\n",
    )
    .unwrap();
    let error = match ilang_cli::build(dir.path(), options) {
        Ok(_) => panic!("ordinary entry acquired a compiler capability"),
        Err(e) => e,
    };
    assert!(
        matches!(&error, ilang_cli::BuildError::Program { codes, .. } if codes.contains(&"E0322")),
        "{error}"
    );
    std::fs::write(
        &main,
        "(helper = app/helper)\nsnapshot = helper.show()\nmain = () { Nil }\n",
    )
    .unwrap();
    let error = match ilang_cli::build(dir.path(), options) {
        Ok(_) => panic!("ordinary initialization acquired a compiler capability"),
        Err(e) => e,
    };
    assert!(
        matches!(&error, ilang_cli::BuildError::Program { codes, .. } if codes.contains(&"E0322")),
        "{error}"
    );
    std::fs::write(&main, "(helper = app/helper)\napply = (f) { f() }\nsnapshot = apply(() { helper.show() })\nmain = () { Nil }\n").unwrap();
    let error = match ilang_cli::build(dir.path(), options) {
        Ok(_) => panic!("ordinary initialization called a compiler capability through a closure"),
        Err(e) => e,
    };
    assert!(
        matches!(&error, ilang_cli::BuildError::Program { codes, .. } if codes.contains(&"E0322")),
        "{error}"
    );
    std::fs::write(
        &main,
        "(helper = app/helper)\nunused = () { helper.show() }\nmain = () { Nil }\n",
    )
    .unwrap();
    ilang_cli::build(dir.path(), options).unwrap();
    std::fs::write(
        &main,
        r#"
(syntax = i/syntax)
@external("test:syntax", "source")
source: () -> syntax.Syntax
main = () -> Nil ? syntax.SyntaxError {
  ! syntax.Definitions = syntax.Definitions((s) { s })
  syntax.definition(source())
  Nil
}
"#,
    )
    .unwrap();
    let error = match ilang_cli::build(dir.path(), options) {
        Ok(_) => panic!("ordinary entry called a compiler-only helper"),
        Err(e) => e,
    };
    assert!(
        matches!(&error, ilang_cli::BuildError::Program { codes, .. } if codes.contains(&"E0322")),
        "{error}"
    );
    std::fs::write(
        &main,
        "@external(\"i:compiler/syntax/v1\", \"show\")\nforged: () -> String\nmain = () { Nil }\n",
    )
    .unwrap();
    let error = match ilang_cli::build(dir.path(), options) {
        Ok(_) => panic!("program declared a compiler-owned external"),
        Err(e) => e,
    };
    assert!(
        matches!(&error, ilang_cli::BuildError::Program { codes, .. } if codes.contains(&"E0306")),
        "{error}"
    );
}

#[test]
fn syntax_values_cross_export_boundary() {
    let dir = tempfile::tempdir().unwrap();
    std::fs::write(
        dir.path().join("i.toml"),
        "name = \"app\"\n[wasm]\nexports = [\"app/main.identity\"]\n",
    )
    .unwrap();
    std::fs::create_dir(dir.path().join("src")).unwrap();
    std::fs::write(
        dir.path().join("src/main.i"),
        "(syntax = i/syntax)\n(identity)\nidentity = (x: syntax.Syntax) { x }\n",
    )
    .unwrap();
    let built = ilang_cli::build(
        dir.path(),
        ilang_cli::BuildOptions {
            tests: false,
            opt: ilang_cli::Level::O0,
            offline: true,
            target: ilang_cli::Target::Ilang,
        },
    )
    .unwrap();
    let mut instance = built
        .host_program()
        .unwrap()
        .instantiate(built.host_options())
        .unwrap();
    let input = Syntax::from_datum(
        &parse("(a b)").unwrap()[0],
        &Scope {
            module: 8,
            marks: BTreeSet::new(),
        },
    );
    let result = instance
        .call(
            "app/main.identity",
            &[ilang_host::syntax::encode(input.clone())],
        )
        .unwrap();
    let ilang_host::Outcome::Ok(value) = result else {
        panic!("export stopped: {result:?}")
    };
    assert!(
        ilang_host::syntax::decode(&value)
            .unwrap()
            .same_code(&input)
    );
}

#[test]
fn compiler_templates_rebuild_through_wasm() {
    let dir = tempfile::tempdir().unwrap();
    std::fs::write(dir.path().join("i.toml"), "name = \"app\"\n").unwrap();
    std::fs::create_dir(dir.path().join("test")).unwrap();
    std::fs::write(
        dir.path().join("test/main.i"),
        r#"
(syntax = i/syntax)
make_many = (value: syntax.Syntax, n: Int, acc: List(syntax.Syntax)) -> List(syntax.Syntax) {
  n |> { 0 -> acc _ -> make_many(value, n - 1, [value, ..acc]) }
}
count = (items: List(syntax.Syntax), n: Int) -> Int {
  items |> { [] -> n [_, ..rest] -> count(rest, n + 1) }
}
@test
exercise = () {
  template = syntax._template(0)
  first = syntax._template(1)
  replacement = syntax._template(2)
  result = syntax._rebuild(template, [first, replacement])
  combined = syntax._append([first, replacement], [first])
  assert(syntax.show(syntax._rebuild(template, combined)) == "(f y f)")
  assert(count(syntax._append(make_many(first, 3000, []), [replacement]), 0) == 3001)
  assert(syntax.show(result) == "(f y)")
  syntax.node(result) |> {
    syntax.Round([_, child]) -> assert(child == replacement)
    _ -> panic("unexpected template")
  }
  Nil
}
"#,
    )
    .unwrap();
    let parsed = parse("(f x) y").unwrap();
    let scope = Scope {
        module: 8,
        marks: BTreeSet::new(),
    };
    let template = Syntax::from_datum(&parsed[0], &scope);
    let ilang_syntax::lisp::syntax::Node::Round(children) = template.node() else {
        panic!("template")
    };
    let templates: std::sync::Arc<[Syntax]> = vec![
        template.clone(),
        children[0].clone(),
        Syntax::from_datum(&parsed[1], &scope),
    ]
    .into();
    for opt in [ilang_cli::Level::O0, ilang_cli::Level::O2] {
        let built = build_generated_tests(dir.path(), opt);
        let mut options = ilang_cli::standard_options();
        ilang_host::syntax::install_with_templates(&mut options.imports, templates.clone())
            .unwrap();
        options
            .imports
            .grant_package(&built.binding_plan, &built.trusted_package);
        let result = built
            .host_program()
            .unwrap()
            .run_test_with("app/main.exercise", options);
        assert!(
            matches!(result, ilang_host::TestResult::Passed),
            "{result:?}"
        );
    }
}

#[test]
fn compiler_quote_patterns_capture_nested_nodes_and_splices() {
    let dir = tempfile::tempdir().unwrap();
    std::fs::write(dir.path().join("i.toml"), "name = \"app\"\n").unwrap();
    std::fs::create_dir(dir.path().join("test")).unwrap();
    std::fs::write(
        dir.path().join("test/main.i"),
        r#"
(syntax = i/syntax)
@test
exercise = () {
  pattern = syntax._template(0)
  input = syntax._template(1)
  matched = syntax._match(pattern, input)
  assert(syntax._match_ok(matched))
  assert(syntax.show(syntax._match_one(matched, 0)) == "x")
  syntax._match_many(matched, 1) |> {
    [a, b] -> {
      assert(syntax.show(a) == "y")
      assert(syntax.show(b) == "z")
    }
    _ -> panic("wrong splice captures")
  }
  failed = syntax._match(pattern, syntax._template(2))
  assert(syntax._match_ok(failed) == False)
  Nil
}
"#,
    )
    .unwrap();
    let parsed = parse("`(f (g ~a) ~..rest) (f (g x) y z) (h x)").unwrap();
    let scope = Scope {
        module: 9,
        marks: BTreeSet::new(),
    };
    let templates: std::sync::Arc<[Syntax]> = parsed
        .iter()
        .map(|d| Syntax::from_datum(d, &scope))
        .collect::<Vec<_>>()
        .into();
    for opt in [ilang_cli::Level::O0, ilang_cli::Level::O2] {
        let built = build_generated_tests(dir.path(), opt);
        let mut options = ilang_cli::standard_options();
        ilang_host::syntax::install_with_templates(&mut options.imports, templates.clone())
            .unwrap();
        options
            .imports
            .grant_package(&built.binding_plan, &built.trusted_package);
        let result = built
            .host_program()
            .unwrap()
            .run_test_with("app/main.exercise", options);
        assert!(
            matches!(result, ilang_host::TestResult::Passed),
            "{result:?}"
        );
    }
}

#[test]
fn compiler_definition_service_returns_and_aborts_at_the_query() {
    use ilang_host::syntax::{DefinitionAbort, DefinitionContext, DefinitionReply};
    use std::sync::Arc;
    let dir = tempfile::tempdir().unwrap();
    std::fs::write(dir.path().join("i.toml"), "name = \"app\"\n").unwrap();
    std::fs::create_dir(dir.path().join("test")).unwrap();
    std::fs::write(
        dir.path().join("test/main.i"),
        r#"
(i/fail, syntax = i/syntax)
@test
answer = () -> Nil ? syntax.SyntaxError ! Assert {
  ! syntax.Definitions = syntax._definitions()
  answer = syntax.definition(syntax._template(0))
  assert(syntax.show(answer) == "(Box {(Box Int)})")
  Nil
}
@test
catchable = () -> Nil ! Assert {
  ! syntax.Definitions = syntax._definitions()
  query = syntax._template(1)
  fail.catch(() { syntax.definition(query) }) |> {
    Error(syntax.SyntaxError(message, at)) -> {
      assert(message == "not visible")
      assert(at == query)
    }
    Ok(_) -> panic("expected an error")
  }
  Nil
}
@test
deferred = () -> Nil ! Assert {
  ! syntax.Definitions = syntax._definitions()
  fail.catch(() { syntax.definition(syntax._template(2)) })
  Nil
}
@test
notes = () -> Nil {
  diagnostics = syntax._diagnostics()
  diagnostics.note("first")
  diagnostics.note("second")
  Nil
}
@test
notes_failed = () -> Nil {
  diagnostics = syntax._diagnostics()
  diagnostics.note("discard me")
  syntax._report_error("failed after note", syntax._template(1))
  Nil
}
@test
macro_error = () -> Nil ! Assert {
  fail.catch(() { syntax._report_error("macro failed", syntax._template(1)) })
  Nil
}
@test
compile_error = () -> Nil ! Assert {
  ! syntax.Definitions = syntax._definitions()
  fail.catch(() { syntax.definition(syntax._template(3)) })
  Nil
}
"#,
    )
    .unwrap();
    let parsed = parse("Box Hidden Waiting Missing (Box {(Box Int)})").unwrap();
    let scope = Scope {
        module: 9,
        marks: BTreeSet::new(),
    };
    let templates: Arc<[Syntax]> = parsed
        .iter()
        .map(|d| Syntax::from_datum(d, &scope))
        .collect::<Vec<_>>()
        .into();
    assert_eq!(templates[4].show(), "(Box {(Box Int)})");
    for opt in [ilang_cli::Level::O0, ilang_cli::Level::O2] {
        let built = build_generated_tests(dir.path(), opt);
        let program = built.host_program().unwrap();
        for name in [
            "answer",
            "catchable",
            "deferred",
            "compile_error",
            "macro_error",
            "notes",
            "notes_failed",
        ] {
            let answer = templates[4].clone();
            let context = Arc::new(DefinitionContext::new(move |of| match of.show().as_str() {
                "Box" => DefinitionReply::Answer(answer.clone()),
                "Hidden" => DefinitionReply::Error {
                    message: "not visible".into(),
                    at: of.clone(),
                },
                "Waiting" => DefinitionReply::Deferred { at: of.clone() },
                "Missing" => DefinitionReply::CompileError {
                    message: "not found".into(),
                    at: of.clone(),
                },
                _ => panic!("unexpected query"),
            }));
            let mut options = ilang_cli::standard_options();
            ilang_host::syntax::install_with_context(
                &mut options.imports,
                templates.clone(),
                Some(context.clone()),
            )
            .unwrap();
            options
                .imports
                .grant_package(&built.binding_plan, &built.trusted_package);
            let result = program.run_test_with(&format!("app/main.{name}"), options);
            match name {
                "answer" | "catchable" => {
                    assert!(
                        matches!(result, ilang_host::TestResult::Passed),
                        "{result:?}"
                    );
                    assert!(context.take_abort().is_none());
                }
                "deferred" => {
                    assert!(!matches!(result, ilang_host::TestResult::Passed));
                    assert!(
                        matches!(context.take_abort(), Some(DefinitionAbort::Deferred { at }) if at.show() == "Waiting")
                    );
                }
                "notes" => {
                    assert!(matches!(result, ilang_host::TestResult::Passed));
                    assert_eq!(context.take_notes(), ["first", "second"]);
                    assert!(context.take_notes().is_empty());
                }
                "notes_failed" => {
                    assert!(!matches!(result, ilang_host::TestResult::Passed));
                    assert!(matches!(
                        context.take_abort(),
                        Some(DefinitionAbort::MacroError { .. })
                    ));
                    // A failed run's context is discarded rather than committed.
                }
                "macro_error" => {
                    assert!(!matches!(result, ilang_host::TestResult::Passed));
                    assert!(
                        matches!(context.take_abort(), Some(DefinitionAbort::MacroError { message, at }) if message == "macro failed" && at.show() == "Hidden")
                    );
                }
                "compile_error" => {
                    assert!(!matches!(result, ilang_host::TestResult::Passed));
                    assert!(
                        matches!(context.take_abort(), Some(DefinitionAbort::CompileError { message, at }) if message == "not found" && at.show() == "Missing")
                    );
                }
                _ => unreachable!(),
            }
        }
    }
}

#[test]
fn compiler_items_service_buffers_valid_requests_and_rejects_bad_ones() {
    use ilang_host::syntax::{
        DefinitionAbort, DefinitionContext, DefinitionReply, ItemContext, ItemRequest,
    };
    use std::sync::Arc;
    let dir = tempfile::tempdir().unwrap();
    std::fs::write(dir.path().join("i.toml"), "name = \"app\"\n").unwrap();
    std::fs::create_dir(dir.path().join("test")).unwrap();
    std::fs::write(
        dir.path().join("test/main.i"),
        r#"
(i/fail, syntax = i/syntax)
@test
item = () -> Nil ? syntax.SyntaxError ! Assert {
  service = syntax._items()
  collection = syntax._template(0)
  target = syntax._template(1)
  at = syntax._template(2)
  service.add(collection, target, [("group", "bench"), ("size", "large")], at)
  service.expose(target)
  fail.catch(() { service.add(collection, target, [("x", "1"), ("x", "2")], at) }) |> {
    Error(syntax.SyntaxError(message, at)) -> { assert(message != "") assert(at == syntax._template(2)) }
    Ok(_) -> panic("duplicate metadata was accepted")
  }
  fail.catch(() { service.add(collection, target, [], syntax._template(3)) }) |> {
    Error(_) -> Nil
    Ok(_) -> panic("unrelated source location was accepted")
  }
  Nil
}
@test
not_item = () -> Nil ! Assert {
  service = syntax._items()
  fail.catch(() { service.expose(syntax._template(1)) })
  Nil
}
"#,
    )
    .unwrap();
    let parsed = parse("(. registry anchor) entry call other").unwrap();
    let caller_scope = Scope {
        module: 12,
        marks: BTreeSet::new(),
    };
    let other_scope = Scope {
        module: 99,
        marks: BTreeSet::new(),
    };
    let templates: Arc<[Syntax]> = parsed
        .iter()
        .enumerate()
        .map(|(i, d)| Syntax::from_datum(d, if i == 3 { &other_scope } else { &caller_scope }))
        .collect::<Vec<_>>()
        .into();
    for opt in [ilang_cli::Level::O0, ilang_cli::Level::O2] {
        let built = build_generated_tests(dir.path(), opt);
        let program = built.host_program().unwrap();
        let run = Arc::new(DefinitionContext::new(|_| -> DefinitionReply {
            panic!("unexpected definition query")
        }));
        let items = Arc::new(ItemContext::new(
            vec![templates[2].clone()].into(),
            templates[2].clone(),
        ));
        let mut options = ilang_cli::standard_options();
        ilang_host::syntax::install_with_items(
            &mut options.imports,
            templates.clone(),
            Some(run.clone()),
            Some(items.clone()),
        )
        .unwrap();
        options
            .imports
            .grant_package(&built.binding_plan, &built.trusted_package);
        let result = program.run_test_with("app/main.item", options);
        assert!(
            matches!(result, ilang_host::TestResult::Passed),
            "{result:?}"
        );
        let requests = items.take_requests();
        assert_eq!(requests.len(), 2);
        match &requests[0] {
            ItemRequest::Add {
                collection,
                target,
                data,
                at,
            } => {
                assert_eq!(collection.show(), "(. registry anchor)");
                assert_eq!(target.show(), "entry");
                assert_eq!(
                    data,
                    &[
                        ("group".into(), "bench".into()),
                        ("size".into(), "large".into())
                    ]
                );
                assert!(at.identical(&templates[2]));
            }
            _ => panic!("expected add request"),
        }
        assert!(matches!(&requests[1], ItemRequest::Expose { name } if name.show() == "entry"));
        assert!(items.take_requests().is_empty());
        let mut options = ilang_cli::standard_options();
        ilang_host::syntax::install_with_items(
            &mut options.imports,
            templates.clone(),
            Some(run.clone()),
            None,
        )
        .unwrap();
        options
            .imports
            .grant_package(&built.binding_plan, &built.trusted_package);
        let result = program.run_test_with("app/main.not_item", options);
        assert!(!matches!(result, ilang_host::TestResult::Passed));
        assert!(
            matches!(run.take_abort(), Some(DefinitionAbort::CompileError { at, .. }) if at.show() == "entry")
        );
    }
}

#[test]
fn committed_item_requests_flip_marks_without_losing_shared_identity() {
    use ilang_host::syntax::{ItemRequest, flip_output_and_requests, flip_requests};
    let target = Syntax::from_datum(
        &parse("entry").unwrap()[0],
        &Scope {
            module: 3,
            marks: BTreeSet::from([7]),
        },
    );
    let requests = vec![
        ItemRequest::Add {
            collection: target.clone(),
            target: target.clone(),
            data: vec![],
            at: target.clone(),
        },
        ItemRequest::Expose {
            name: target.clone(),
        },
    ];
    let flipped = flip_requests(&requests, 7);
    let ItemRequest::Add {
        collection,
        target: named,
        at,
        ..
    } = &flipped[0]
    else {
        panic!("add")
    };
    let ItemRequest::Expose { name } = &flipped[1] else {
        panic!("expose")
    };
    assert!(collection.scope().marks.is_empty());
    assert!(collection.identical(named));
    assert!(collection.identical(at));
    assert!(collection.identical(name));
    let (output, shared) = flip_output_and_requests(&target, &requests, 7);
    let ItemRequest::Add { target, .. } = &shared[0] else {
        panic!("add")
    };
    let ItemRequest::Expose { name } = &shared[1] else {
        panic!("expose")
    };
    assert!(output.identical(target));
    assert!(output.identical(name));
}

#[test]
fn compiler_service_budgets_stop_before_observable_contributions() {
    use ilang_host::macro_budget::{Limit, Limits, MacroBudget};
    use ilang_host::syntax::{DefinitionContext, DefinitionReply, ItemContext};
    use std::sync::{
        Arc,
        atomic::{AtomicUsize, Ordering},
    };
    let dir = tempfile::tempdir().unwrap();
    std::fs::write(dir.path().join("i.toml"), "name = \"app\"\n").unwrap();
    std::fs::create_dir(dir.path().join("test")).unwrap();
    std::fs::write(
        dir.path().join("test/main.i"),
        r#"
(syntax = i/syntax)
@test
note = () {
  diagnostics = syntax._diagnostics()
  diagnostics.note("abcdefghijklmnopqrstuvwxyzabcdefghijklmnopqrstuvwxyz")
  Nil
}
@test
query = () -> Nil ? syntax.SyntaxError {
  ! syntax.Definitions = syntax._definitions()
  syntax.definition(syntax._template(0))
  Nil
}
@test
item = () -> Nil ? syntax.SyntaxError {
  service = syntax._items()
  service.add(syntax._template(1), syntax._template(2), [], syntax._template(2))
  Nil
}
"#,
    )
    .unwrap();
    let parsed =
        parse("(Large a b c d e f g h i j k l m n o p q r s t) collection target").unwrap();
    let scope = Scope {
        module: 7,
        marks: BTreeSet::new(),
    };
    let templates: Arc<[Syntax]> = parsed
        .iter()
        .map(|d| Syntax::from_datum(d, &scope))
        .collect::<Vec<_>>()
        .into();
    let built = build_generated_tests(dir.path(), ilang_cli::Level::O0);
    let program = built.host_program().unwrap();
    for name in ["note", "query", "item"] {
        let calls = Arc::new(AtomicUsize::new(0));
        let callback_calls = calls.clone();
        let context = Arc::new(DefinitionContext::new(move |s| {
            callback_calls.fetch_add(1, Ordering::SeqCst);
            DefinitionReply::Answer(s.clone())
        }));
        let items = Arc::new(ItemContext::new(
            vec![templates[0].clone(), templates[2].clone()].into(),
            templates[2].clone(),
        ));
        let budget = MacroBudget::new(Limits {
            work: 20,
            allocation: 1_000_000,
            frames: 10_000,
        });
        let mut options = ilang_cli::standard_options();
        ilang_host::syntax::install_with_budget(
            &mut options.imports,
            templates.clone(),
            Some(context.clone()),
            Some(items.clone()),
            budget.clone(),
        )
        .unwrap();
        options
            .imports
            .grant_package(&built.binding_plan, &built.trusted_package);
        let result = program.run_test_with(&format!("app/main.{name}"), options);
        assert!(
            !matches!(result, ilang_host::TestResult::Passed),
            "{name}: {result:?}"
        );
        assert_eq!(budget.exceeded(), Some(Limit::Work), "{name}");
        assert_eq!(calls.load(Ordering::SeqCst), 0, "{name}");
        assert!(context.take_notes().is_empty());
        assert!(items.take_requests().is_empty());
    }
}

#[test]
fn compiler_syntax_helpers_are_private_to_generated_code() {
    let dir = tempfile::tempdir().unwrap();
    std::fs::write(dir.path().join("i.toml"), "name = \"app\"\n").unwrap();
    std::fs::create_dir(dir.path().join("src")).unwrap();
    std::fs::write(
        dir.path().join("src/main.i"),
        "(syntax = i/syntax)\nmain = () { syntax._template(0) Nil }\n",
    )
    .unwrap();
    let error = match ilang_cli::build(
        dir.path(),
        ilang_cli::BuildOptions {
            tests: false,
            opt: ilang_cli::Level::O0,
            offline: true,
            target: ilang_cli::Target::Ilang,
        },
    ) {
        Ok(_) => panic!("ordinary code accessed a compiler helper"),
        Err(error) => error,
    };
    assert!(
        matches!(&error, ilang_cli::BuildError::Program { codes, .. } if codes.contains(&"E0204")),
        "{error}"
    );
}
